module benchmark/solution

import std/fs (readFile, writeFile)
import std/string (stringToInt, trim)
import std/option (Some, None)

pure func calculateTotal(price: int, quantity: int) -> int = price * quantity

func readPrice(filename: string) -> int ! {FS} {
  let content = readFile(filename);
  match stringToInt(trim(content)) {
    Some(price) => price,
    None => 0
  }
}

func displayOrder(product: string, total: int) -> () ! {IO} =
  println("Order: ${product} = $${total}")

func processOrder(product: string, priceFile: string, quantity: int) -> () ! {IO, FS} {
  let price = readPrice(priceFile);
  let total = calculateTotal(price, quantity);
  displayOrder(product, total)
}

export func main() -> () ! {IO, FS} {
  writeFile("widget_price.txt", "15");
  processOrder("Widget", "widget_price.txt", 4)
}

